-- 2026-11-18: Music Performance Trust Fund / John Floeter (CFM Local 10-208). Grant-row only (no new partner row: Stephen has not approved one).
-- Logs John's Nov 4 reply (BOB .eml) and Stephen's one-line reply SENT at his "send" (Resend 01a1f225-d671-7187-a372-a952173a9c92, threaded on John's message,
-- links https://selassiefest.com/full-spectrum/cfm/). Replaces the wrong "send a Nov 7 nudge" step. Guarded; safe to re-run.
begin;
update fs_grant_deadlines
set next_step='REPLY SENT Nov 18, 2026 (Resend 01a1f225-d671-7187-a372-a952173a9c92), threaded on John Floeter''s Nov 4 email, linking our proposal page https://selassiefest.com/full-spectrum/cfm/ (Wed Jul 21, 2027 Rainbow Wednesday with Ifficial Reggae Movement + featured singer JayRebl and young DJs; about 5 players x ~$250 = ~$1,250, MPTF ~50% = ~$625; asks: non-union players OK? 6 weeks or 45 days?). Ball with John. If silent, one email nudge Dec 2 (internal); calls parked. After his go-ahead: Paul signs the W-9 and we sign the MPTF terms. Paperwork due in his office 6 weeks before (Jun 9, 2027 for Jul 21) or 45 days (Jun 6), whichever he says.',
    next_step_due='2026-12-02',
    notes=coalesce(notes,'')||E'\n[2026-11-18] John Floeter (VP, CFM Local 10-208, jfloeter@cfm10208.org, 312.782.0063 x222, cell 847-477-4970) replied Nov 4 2026 18:59:59 UTC, Message-ID <CH2PR22MB2008124493BEAEBC1C1A6BAFF4682@CH2PR22MB2008.namprd22.prod.outlook.com> (in reply to our Oct 31 email): may co-sponsor 1 or 2 events; MPTF co-funds ~50% of performer wages and cartage (Community Engagement Scale $158.50; side-musician minimum take-home $174.35; ~$250/person all in; tech and rentals excluded); DJs can qualify; union membership preferred, not required; no recording; info due 6 weeks before the performance (he also wrote 45 days); check comes to us after the performance and we pay the leader; asked for a rough number of musicians and proposal. Restrictions attachment lists workshops, graduation, fundraisers, recording, religious services, commercial advantage as NOT funded. Our reply (Resend 01a1f225-d671-7187-a372-a952173a9c92) sent Nov 18 evening, the earlier Nov 7 nudge step was wrong (John had already replied). Funder: musicpf.org (record-label royalty fund; local union is the only door; MPTF pays professional union musicians for free live public events). The Nov 4 reply sat unanswered until Nov 18.'
where id='dc89e16f-2331-437b-b4dd-66a54ca834c5' and coalesce(notes,'') not like '%01a1f225-d671-7187%';
commit;
select next_step_due, notes like '%01a1f225-d671-7187%' logged, left(next_step,60) ns from fs_grant_deadlines where id='dc89e16f-2331-437b-b4dd-66a54ca834c5';
